files.content:
:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --accent: #ff6b6b;
  --accent-hover: #ff8e8e;
  --accent-pressed: #e05555;
  --border: #3a3a55;
  --shadow: rgba(0, 0, 0, 0.4);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.app {
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  text-align: center;
}

h1 {
  font-size: 1.8rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--text);
}

.deck-info {
  display: flex;
  justify-content: space-between;
  font-size: 1rem;
  color: var(--text);
  opacity: 0.8;
}

.card {
  perspective: 1000px;
  cursor: pointer;
  outline: none;
  border-radius: 16px;
  box-shadow: 0 8px 20px var(--shadow);
  transition: box-shadow 0.2s;
}

.card:focus-visible {
  box-shadow: 0 0 0 4px var(--accent);
}

.card-inner {
  position: relative;
  width: 100%;
  height: 260px;
  transition: transform 0.5s;
  transform-style: preserve-3d;
  border-radius: 16px;
}

.card.flipped .card-inner {
  transform: rotateY(180deg);
}

.card-front,
.card-back {
  position: absolute;
  inset: 0;
  backface-visibility: hidden;
  border-radius: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: var(--card-bg);
  border: 2px solid var(--border);
  gap: 12px;
}

.card-back {
  transform: rotateY(180deg);
}

.card-label {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  opacity: 0.6;
}

#word-text,
#meaning-text {
  font-size: 1.6rem;
  font-weight: 600;
  word-break: break-word;
}

#meaning-text {
  font-size: 1.3rem;
  font-weight: 400;
  line-height: 1.4;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  background: var(--card-bg);
  color: var(--text);
  border: 2px solid var(--border);
  border-radius: 12px;
  padding: 12px 20px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, transform 0.1s;
  flex: 1 1 auto;
  min-width: 100px;
}

button:hover {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button:active {
  background: var(--accent-pressed);
  border-color: var(--accent-pressed);
  transform: scale(0.97);
}

#got-it-btn {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

#got-it-btn:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

#got-it-btn:active {
  background: var(--accent-pressed);
  border-color: var(--accent-pressed);
}

@media (max-width: 400px) {
  body {
    font-size: 16px;
    padding: 12px;
  }
  .card-inner {
    height: 200px;
  }
  #word-text {
    font-size: 1.3rem;
  }
  #meaning-text {
    font-size: 1.1rem;
  }
  button {
    padding: 10px 14px;
    font-size: 0.95rem;
  }
}

const cards = [
  { word: 'Ephemeral', meaning: 'Lasting for a very short time.' },
  { word: 'Serendipity', meaning: 'The occurrence of happy or beneficial events by chance.' },
  { word: 'Resilient', meaning: 'Able to recover quickly from difficulties.' },
  { word: 'Meticulous', meaning: 'Showing great attention to detail; very careful and precise.' },
  { word: 'Ambiguous', meaning: 'Open to more than one interpretation; not having one obvious meaning.' }
];

let currentIndex = 0;
let flipped = false;
const knownSet = new Set();

const cardEl = document.getElementById('card');
const wordText = document.getElementById('word-text');
const meaningText = document.getElementById('meaning-text');
const cardCounter = document.getElementById('card-counter');
const knownCountEl = document.getElementById('known-count');
const prevBtn = document.getElementById('prev-btn');
const nextBtn = document.getElementById('next-btn');
const gotItBtn = document.getElementById('got-it-btn');

function render() {
  const card = cards[currentIndex];
  wordText.textContent = card.word;
  meaningText.textContent = card.meaning;
  cardCounter.textContent = `Card ${currentIndex + 1} of ${cards.length}`;
  knownCountEl.textContent = `Known: ${knownSet.size}`;
  cardEl.classList.toggle('flipped', flipped);
  cardEl.setAttribute('aria-label', `Flashcard ${currentIndex + 1} of ${cards.length}. ${flipped ? 'Meaning shown: ' + card.meaning : 'Word shown: ' + card.word}. Click or press Enter to flip.`);
  prevBtn.disabled = currentIndex === 0;
  nextBtn.disabled = currentIndex === cards.length - 1;
  gotItBtn.disabled = knownSet.has(currentIndex);
}

function flipCard() {
  flipped = !flipped;
  render();
}

function goTo(index) {
  if (index < 0 || index >= cards.length) return;
  currentIndex = index;
  flipped = false;
  render();
}

function markKnown() {
  if (!knownSet.has(currentIndex)) {
    knownSet.add(currentIndex);
    render();
  }
}

cardEl.addEventListener('click', flipCard);
cardEl.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' || e.key === ' ') {
    e.preventDefault();
    flipCard();
  }
});

prevBtn.addEventListener('click', () => goTo(currentIndex - 1));
nextBtn.addEventListener('click', () => goTo(currentIndex + 1));
gotItBtn.addEventListener('click', markKnown);

render();
